import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"溫公易說 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"溫公易說 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"classics/wengong/058.md","filePath":"classics/wengong/058.md"}'),l={name:"classics/wengong/058.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><h3 id="彖曰-重巽以申命。剛巽乎中正而志行-柔皆順乎剛-是以小亨-利有攸往-利見大人。" tabindex="-1">彖曰：重巽以申命。剛巽乎中正而志行，柔皆順乎剛，是以小亨，利有攸往，利見大人。 <a class="header-anchor" href="#彖曰-重巽以申命。剛巽乎中正而志行-柔皆順乎剛-是以小亨-利有攸往-利見大人。" aria-label="Permalink to “彖曰：重巽以申命。剛巽乎中正而志行，柔皆順乎剛，是以小亨，利有攸往，利見大人。”">​</a></h3><h3 id="象曰-隨風-巽。君子以申命行事。" tabindex="-1">象曰：隨風，巽。君子以申命行事。 <a class="header-anchor" href="#象曰-隨風-巽。君子以申命行事。" aria-label="Permalink to “象曰：隨風，巽。君子以申命行事。”">​</a></h3><h3 id="初六-進退-利武人之貞-象曰-進退-志疑也。利武人之貞-志治也。" tabindex="-1">初六：進退，利武人之貞 象曰：進退，志疑也。利武人之貞，志治也。 <a class="header-anchor" href="#初六-進退-利武人之貞-象曰-進退-志疑也。利武人之貞-志治也。" aria-label="Permalink to “初六：進退，利武人之貞 象曰：進退，志疑也。利武人之貞，志治也。”">​</a></h3><h3 id="九二-巽在床下-用史巫紛若-吉-無咎-象曰-紛若之吉-得中也。" tabindex="-1">九二：巽在床下，用史巫紛若，吉，無咎 象曰：紛若之吉，得中也。 <a class="header-anchor" href="#九二-巽在床下-用史巫紛若-吉-無咎-象曰-紛若之吉-得中也。" aria-label="Permalink to “九二：巽在床下，用史巫紛若，吉，無咎 象曰：紛若之吉，得中也。”">​</a></h3><h3 id="九三-頻巽-吝-象曰-頻巽之吝-志窮也。" tabindex="-1">九三：頻巽，吝 象曰：頻巽之吝，志窮也。 <a class="header-anchor" href="#九三-頻巽-吝-象曰-頻巽之吝-志窮也。" aria-label="Permalink to “九三：頻巽，吝 象曰：頻巽之吝，志窮也。”">​</a></h3><h3 id="六四-悔亡-田獲三品-象曰-田獲三品-有功也。" tabindex="-1">六四：悔亡，田獲三品 象曰：田獲三品，有功也。 <a class="header-anchor" href="#六四-悔亡-田獲三品-象曰-田獲三品-有功也。" aria-label="Permalink to “六四：悔亡，田獲三品 象曰：田獲三品，有功也。”">​</a></h3><h3 id="九五-貞吉-悔亡-無不利-無初有終。先庚三日-後庚三日-吉-象曰-九五之吉-位正中也。" tabindex="-1">九五：貞吉，悔亡，無不利，無初有終。先庚三日，後庚三日，吉 象曰：九五之吉，位正中也。 <a class="header-anchor" href="#九五-貞吉-悔亡-無不利-無初有終。先庚三日-後庚三日-吉-象曰-九五之吉-位正中也。" aria-label="Permalink to “九五：貞吉，悔亡，無不利，無初有終。先庚三日，後庚三日，吉 象曰：九五之吉，位正中也。”">​</a></h3><p>巽之彖曰：重巽以申命。重巽，隨風也。隨風者，申命之象也。風為號令。九五之君，為號令之主，得位以行其令，不失其中正，故曰貞吉，悔亡，無不利。民可與樂成，難與慮始，故曰無初有終。庚屬西方金，金主制。號令不嚴則不行，故先庚三日，後庚三日，吉也。</p><h3 id="上九-巽在床下-喪其資斧-貞兇-象曰-巽在床下-上窮也。喪其資斧-正乎兇也。" tabindex="-1">上九：巽在床下，喪其資斧，貞兇 象曰：巽在床下，上窮也。喪其資斧，正乎兇也。 <a class="header-anchor" href="#上九-巽在床下-喪其資斧-貞兇-象曰-巽在床下-上窮也。喪其資斧-正乎兇也。" aria-label="Permalink to “上九：巽在床下，喪其資斧，貞兇 象曰：巽在床下，上窮也。喪其資斧，正乎兇也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
